exec tool declaration:
```ts
declare const tools: { mcp__codex_apps__heptaruntime_mac_controller_operation_start(args: {
  // Required private 1..128-byte key, unchanged typed arguments must reuse the same key.
  idempotency_key: string;
  operation: { arguments: {
  // One configured operator host. Caller-selected SSH targets are unavailable.
  host: string;
  // Full-file byte ceiling, 1..65536; default 16384. Larger files fail, never truncate.
  max_file_bytes?: number;
  // Shared serialized MCP text-result ceiling, 1024..262144; default 65536.
  // Includes JSON escaping. A failed batch returns no partial file content.
  max_response_bytes?: number;
  // 1..16 distinct absolute regular-file paths; symlinks and hardlinks are rejected.
  paths: Array<string>;
}; tool: "read_multiple_files"; } | { arguments: { host: string; path: string; }; tool: "file_info"; } | { arguments: {
  // Bind every chunk to the version returned by the first read.
  expected_version?: string;
  host: string;
  // Maximum returned bytes; capped at 64 KiB. Use next_offset until eof.
  limit?: number;
  offset?: number;
  path: string;
}; tool: "binary_read"; } | { arguments: { host: string; job_id: string; }; tool: "process_status"; } | { arguments: {
  host: string;
  job_id: string;
  // Maximum bytes returned per stream, capped at 16 KiB with lossless byte cursors.
  limit?: number;
  stderr_offset?: number;
  stdout_offset?: number;
}; tool: "process_read"; } | { arguments: {
  host: string;
  job_id: string;
  // Maximum wait for this call, capped at 30 seconds.
  timeout_seconds?: number;
}; tool: "process_wait"; } | { arguments: { host?: string; }; tool: "process_list"; } | { arguments: { host: string; }; tool: "hardware_snapshot"; } | { arguments: {
  host: string;
  // Exact systemd unit or launchd label names, max 64.
  services: Array<string>;
}; tool: "service_status"; } | { arguments: { host: string; }; tool: "network_inspect"; };
}): Promise<CallToolResult>; };
